CREATE COLUMN TABLE "TEST_AP"."OBBQ" ("AbsEntry" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50), "SnBMDAbs" INTEGER CS_INT NOT NULL , "BinAbs" INTEGER CS_INT NOT NULL , "OnHandQty" DECIMAL(21,6) CS_FIXED, "WhsCode" NVARCHAR(8), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBBQ_BUSINESS_K" ON "TEST_AP"."OBBQ" ( "SnBMDAbs" ASC, "BinAbs" ASC );
CREATE INDEX "OBBQ_BIN_ABS" ON "TEST_AP"."OBBQ" ( "BinAbs" ASC )